-- 엔티티도 담긴다

@Test
void 엔티티_담기() {
    em.clear();
    Tuple t = queryFactory
            .select(member, team.name)
            .from(member)
            .leftJoin(member.team, team)
            .where(member.username.eq("m1"))
            .fetchOne();

    System.out.println("회원: " + t.get(member).getUsername());
    System.out.println("팀:   " + t.get(team.name));
}

