-- 표현식이 같으면 읽힌다

@Test
void 동등성() {
    em.clear();
    Tuple t = queryFactory
            .select(member.age.sum(), member.age.avg())
            .from(member)
            .fetchOne();

    NumberExpression<Integer> otherSum = member.age.sum();
    System.out.println("같은 객체? " + (otherSum == member.age.sum()));
    System.out.println("값:        " + t.get(otherSum));
}

