-- 인덱스로 읽으면

@Test
void 인덱스() {
    em.clear();
    Tuple t = queryFactory
            .select(member.username, member.age)
            .from(member)
            .where(member.username.eq("m1"))
            .fetchOne();

    System.out.println("0: " + t.get(0, String.class));
    System.out.println("1: " + t.get(1, Integer.class));
    System.out.println("크기: " + t.size());
    System.out.println("배열: " + Arrays.toString(t.toArray()));
}

