-- 타입을 틀리면

@Test
void 타입_오류() {
    em.clear();
    Tuple t = queryFactory
            .select(member.username, member.age)
            .from(member)
            .where(member.username.eq("m1"))
            .fetchOne();

    try {
        System.out.println(t.get(0, Integer.class));
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
    }
}

예외: ClassCastException

