-- 순서를 바꾸면 조용히 틀린다

@Test
void 순서_변경() {
    em.clear();
    // select(member.age, member.username) 로 바꿨다고 하자
    Tuple t = queryFactory
            .select(member.age, member.username)
            .from(member)
            .where(member.username.eq("m1"))
            .fetchOne();

    System.out.println("표현식: " + t.get(member.username));
    try {
        System.out.println("인덱스: " + t.get(0, String.class));
    } catch (Exception e) {
        System.out.println("인덱스: " + e.getClass().getSimpleName());
    }
}

