@Test
void null_원소() {
    em.clear();
    List<Tuple> r = queryFactory
            .select(member.username, team.name)
            .from(member)
            .leftJoin(member.team, team)
            .where(member.username.eq("m8"))
            .fetch();

    Tuple t = r.get(0);
    System.out.println("이름: " + t.get(member.username));
    System.out.println("팀:   " + t.get(team.name));
    try {
        System.out.println(t.get(team.name).length());
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
    }
}

