@Repository
public class MemberQueryRepository {

    public List<MemberSummary> findSummaries() {
        return queryFactory
                .select(member.username, member.age, team.name)
                .from(member)
                .leftJoin(member.team, team)
                .fetch()
                .stream()
                .map(t -> new MemberSummary(
                        t.get(member.username),
                        t.get(member.age),
                        t.get(team.name)))
                .toList();
    }
}

public record MemberSummary(String username, int age, String teamName) {}

